package com.trough.hot;
import android.os.*;import android.view.*;import java.io.File;import java.util.ArrayList;import org.json.JSONObject;
/** Close only this simulator and acknowledge after its render workers release native contexts. */
final class HalfSwordSceneClose implements Runnable {
 final ArrayList<HalfSwordView> views=new ArrayList<HalfSwordView>();final ArrayList<View> panels=new ArrayList<View>();final Handler ui=new Handler(Looper.getMainLooper());final File directory;final long began=SystemClock.uptimeMillis();
 HalfSwordSceneClose(HalfSwordView source){directory=new File(source.getContext().getFilesDir(),"home/.trough");collect(source.getRootView());for(HalfSwordView v:views){v.characterRunning=false;v.cancelAllTouchInputs();}for(View p:panels)if(p.getParent() instanceof ViewGroup)((ViewGroup)p.getParent()).removeView(p);ui.post(this);}
 void collect(View v){if(v instanceof HalfSwordView)views.add((HalfSwordView)v);if("half-sword-preview".equals(v.getTag())||"half-sword-expanded".equals(v.getTag()))panels.add(v);if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int i=0;i<g.getChildCount();i++)collect(g.getChildAt(i));}}
 static boolean maybeRun(HalfSwordView source){File ticket=new File(source.getContext().getFilesDir(),"home/.trough/half-sword-close-request");if(!ticket.delete())return false;new HalfSwordSceneClose(source);return true;}
 public void run(){int workers=0;boolean releaseFailed=false;for(HalfSwordView v:views){workers+=v.renderWorkers.get();releaseFailed|=v.renderReleaseFailed;}boolean closed=workers==0&&!releaseFailed;if(!closed&&SystemClock.uptimeMillis()-began<5000){ui.postDelayed(this,25);return;}if(closed){new File(directory,"half-sword-present").delete();new File(directory,"half-sword-preview").delete();new File(directory,"half-sword-expanded").delete();}try{JSONObject result=new JSONObject();result.put("closed",closed).put("release_failed",releaseFailed).put("render_workers",workers).put("views",views.size()).put("panels",panels.size()).put("time_ms",System.currentTimeMillis());Payloads.writeSmall(new File(directory,"half-sword-close-result.json"),result.toString());}catch(Exception ignored){}}
}
